"""Create local-only analysis and labeled reference/output comparison PNGs."""
from pathlib import Path
import argparse,csv,html,json
from PIL import Image,ImageDraw,ImageFont

def comparison(root,output_files,outfile,title):
    pairs=[('character.png',output_files[0],'Character conversation / scale comparison'),('office.png',output_files[1],'Period interior / reaction'),('staging.png',output_files[2],'Illustrated explanation board'),('full-figures.png',output_files[3],'Full figures / perspective set')]
    w,h=960,480;canvas=Image.new('RGB',(w*2,90+len(pairs)*(h+44)),'#eee8db');d=ImageDraw.Draw(canvas)
    fontfile=Path(__file__).resolve().parents[1]/'examples/skills/ink-history/kit/assets/LilitaOne-Regular.ttf'
    font=ImageFont.truetype(str(fontfile),26);small=ImageFont.truetype(str(fontfile),21)
    d.text((22,8),title,fill='#30252a',font=font);d.text((22,46),'REFERENCE (study only)',fill='#30252a',font=small);d.text((w+22,46),'ORIGINAL OUTPUT — same shot category, different story',fill='#30252a',font=small)
    for i,(ref,file,label) in enumerate(pairs):
        y=90+i*(h+44)
        for x,f in [(0,root/ref),(w,Path(file))]:
            image=Image.open(f).convert('RGB');image.thumbnail((w,h));canvas.paste(image,(x,y))
        d.text((18,y+h+7),label,fill='#30252a',font=small)
    canvas.save(outfile);return outfile

def analysis(root):
    j=json.loads((root/'measurements.json').read_text());caps=json.loads((root/'captions.json').read_text());cuts=[0]+j['candidateCuts']+[j['duration']]
    with (root/'shot-candidates.csv').open('w',newline='') as f:
        w=csv.writer(f);w.writerow(['segment','start_seconds','end_seconds','duration_seconds','method'])
        for i,(a,b) in enumerate(zip(cuts,cuts[1:])):w.writerow([i+1,round(a,4),round(b,4),round(b-a,4),'scene score > .22, not all editorial cuts'])
    body='''<h1>Historically reference: visual and timing study</h1>
<p>Source: <a href="https://www.youtube.com/watch?v=w5mhZs73Qwc">WORLD WAR 1 [No AI] — Historically</a>, published 21 June 2026. Downloaded for this local study with yt-dlp; the source and its derived frames are deliberately outside the distributed skill. Description, metadata and three English subtitle files are retained here. An automatic-caption language batch hit HTTP 429 after the English files; a second media download completed. yt-dlp's merge expected a filename without .part; FFmpeg remuxed the complete video/audio downloads without re-encoding.</p>
<h2>Evidence and limits</h2><p>Inspected all six overview sheets (187 stills at ten-second sampling), full-resolution character/set/board stills, and native 60fps frame strips from selected one-second intervals (600 extracted frames). These establish a limited-animation 2D look; this was not inferred from the title. Dense strips cover a door opening, a console insert, dialogue poses, a full-width map, a battle gag, an interior, and a wide crowd. They are not a claim that all 112,256 source frames were manually inspected. Automatic scene detection measured the complete file. The audio observations below distinguish measurements from inferences: this environment did not provide reliable subjective audio playback, so timbre and exact voice/music separation remain unverified.</p>
<h2>Format, timing and narrative</h2><table><tr><th>Property</th><th>Observed result</th></tr><tr><td>Picture</td><td>1920×960; 2:1; 60 fps; AV1 in the downloaded encode; 1870.933s picture / approximately 1871s container.</td></tr><tr><td>Structure</td><td>31:11 long-form comedic WWI explainer, framed as two recurring cartoon hosts inside a video game. Intro, narrated geographic explanations, dramatized period scenes, game/interface jokes, sponsor segment, closing sequence. This is not a vertical fact short.</td></tr><tr><td>Strong cut candidates</td><td>226 detected transitions with scene score &gt;.22 on 192px-wide analysis. Intervals: median 7.233s, mean 8.242s, 10th–90th percentiles 1.31–15.98s. See shot-candidates.csv for every boundary and length. Map moves and similar pose cuts can evade this threshold; do not equate it with exact shot count.</td></tr><tr><td>Intro rhythm</td><td>0–43s has 12 strong segments; median 2.85s. Boundaries 4.583, 5.900, 9.817, 17.733, 21.850, 22.267, 24.050, 24.400, 24.767, 35.750, 42.450. The cluster around 24s shows a short insertion/interaction montage.</td></tr><tr><td>Narration</td><td>5260 subtitle tokens by simple word regex; 2.811 words/s over full runtime; median caption-segment rate 2.941 words/s. This includes some bracketed dialogue/interface captions and sponsor text, so it is an estimate of spoken pace, not a word-perfect transcript. Natural sentence pauses range from near-contiguous delivery to several tenths of a second, with longer comic/gameplay pauses.</td></tr><tr><td>Master audio</td><td>FFmpeg EBU measurement: −15.37 LUFS integrated, +0.91dBTP, 5.30 LU loudness range, gate −25.65 LUFS. Stereo encode. Exact voice/music/SFX level ratios cannot be recovered without stems; no fabricated ratio is used.</td></tr></table>
<h2>Character construction, line and color</h2><p>The protagonists are white oval/bean-faced drawn cutouts, dark warm ink, minimal eyes, elastic mouths, and strongly asymmetric hair. Costume, silhouette, facial hair and pose carry identity. Faces are white with gray/mauve shadow shapes rather than realistic skin. The primary host has a large dark-purple hair silhouette and a small facial-hair accent; the companion has a very simple blank white face. These recognizable hosts and costumes are not distributed in the kit. Period characters use hats, coat lapels, belts, medals, cuffs and period tools. Contours appear around 5–12px thick at this resolution, with thinner interior seams and tapered drawn accents.</p>
<p>At 66s the left foreground face/hair/helmet mass fills about half the picture width; its visible face spans approximately x270–1040 and y270–790. The right character sits behind it, with a smaller face around x1270–1690, y320–770. Intentional close crops leave the eyes and mouth fully readable. Other conversation images use face widths around 20–35% of frame width. Full-body figures on a period street occupy roughly 45–80% of picture height. Map figures may be tiny because the country or army formation is the subject. This does not justify tiny primary characters in dialogue shots.</p>
<p>Palette changes by location: ochre and cream skylight, warm brown ink, olive foliage, brown/stone architecture and desaturated clothes outside; plum/indigo gaming-room interiors; blue-green water; saturated red/green/yellow political regions on maps. Shadows are broad graphic planes with selected gradient/brush variation and brighter edge accents. Faces and hands remain high-contrast. There is a restrained edge vignette, not photorealistic depth of field. Background texture reads as paint/paper rather than a repeated noise overlay.</p>
<h2>Worlds, staging and camera</h2><p>Sets are carefully illustrated perspective spaces with irregular buildings, broken-up roof silhouettes, near-black window openings, stone/wood seams, layered foliage and curved cloud masses. Foreground walls, furniture or trees overlap other layers. Canal and street views have a clear vanishing point and strong warm/cool separation. Interiors include readable small props, curtains, wall art, book stacks, lamps and directed light. Subject placement is intentionally asymmetric, leaving room for a gesture, secondary reaction or gag object. The environment is full without dominating the characters.</p>
<p>The editor alternates an asymmetric close two-shot, full-figure staging, large object inserts, maps with faces and arrows, diagrams, reaction close-ups, and occasional deliberately simplified joke backgrounds. Maps use textured blue water, parchment/halftone land, colored regions, border highlights, floating original icons and drawn country faces. The blue explanation board uses off-white line drawings, a warm wooden surround, a pencil and eraser; its header is a short bold label, not a lower-third subtitle track.</p>
<p>Native-frame strips show limited animation: a pose can hold across many 60fps frames, while a door or hand snaps through a short eased action. At 1.10–1.22s the opening door reveals the host in about 0.12s, followed by a hold and a small hand/face change. The 65s dialogue sample has subtle head/camera movement and distinct held expressions, rather than every part wiggling continuously. The 350s battlefield sample contains a quick muzzle-flash-like action and small reactions while the wide setup holds. Camera language includes small pushes/pans, an occasional fast reaction punch, and hard cuts. Strong scene detection misses many internal actions. Do not replace these events with an endless zoom on a static card.</p>
<h2>Text, sound decisions and originality</h2><p>The sampled narrative does not carry constant burned-in subtitles. Text is diegetic (signs, maps, papers), an emphatic bold outlined name/date, a diagram annotation or a game/news interface. Small source labels vary greatly, but a reusable kit should enforce at least 36px for normal delivery labels and keep them out of faces. Comic balloon text must be brief.</p>
<p>The description says music and sound are licensed from Envato Elements. Caption evidence and visual contacts imply game/menu noises, gun/object contacts, comic stings and scene-specific effects, but subjective timbre and the exact relative mix were not verified by ear here. The kit therefore synthesizes an original light plucked/mallet bed, paper/stamp/bell/tick/swish cues, and a final sting, with numerical checks. Music starts about 19dB below active speech RMS, effects are quieter than voice peaks, and the finished master targets −16 LUFS / −1.5dBTP. These are production choices, not claimed copies of the original soundtrack. Kokoro's local voice does not reproduce the human narrator's improvisation, dialogue performance or comic delivery.</p>
<h2>Chosen implementation and comparison</h2><p>Canvas 2D with native Skia (@napi-rs/canvas) is the closest reliable free local foundation: original SVG-like paths, layered shaded cutouts, cached illustrated backgrounds, deterministic per-frame acting, direct raw-frame piping to FFmpeg, local Kokoro narration, NumPy sound synthesis. No browser/GPU service is needed. The 3D primitive/card approach would introduce the wrong materials, camera space and silhouette treatment.</p>
<p>The worked example is the original fictional “The Mayor Who Arrested Time,” not a copied WWI script. Its comparison PNG pairs matching shot categories rather than pretending unrelated frames have matching narrative timing. Iteration corrected visible fleck texture, accidental tall-hat cropping, weak grounding, indistinguishable cast silhouettes and insufficient paper-pile action. Automated geometry and loudness gates are only a floor.</p>
<p><strong>Honest quality read:</strong> the broad 2D format, large white-faced cast, warm ink palette, illustrated period staging, reaction poses, explanation board and widescreen composition are reproduced. The output is still simpler and more uniform: clean procedural contours, less intricate painting, fewer bespoke silhouettes and camera angles, generic reusable pose vocabulary, floating insert props in some shots, and synthetic narration/sound. It is not indistinguishable from the reference or demonstrably “by the same hand.” Closing that gap requires more authored background paintings, varied face/hand/pose drawings, per-story physical interactions and human-level narration/editing. Do not present numerical QA as proof of that artistic bar.</p>
<h2>Reference stills and sampling record</h2>'''
    for name,label in [('character.png','66s: foreground conversation scale and cel shadows'),('office.png','1145s: shaded period interior and expressive staging'),('staging.png','180s: large line-art explanation board'),('full-figures.png','385s: full figures grounded in a perspective street'),('first-look.png','100s: textured animated political map')]:body+=f'<figure><img src="{name}"><figcaption>{label}</figcaption></figure>'
    body+='<p>Full overview sheets: '+', '.join(f'<a href="overview-{i}.jpg">{i}</a>' for i in range(1,7))+'. Native-frame strips: motion-{1,15,65,106,180,350,600,910,1380,1750}-{0,30}.jpg. Raw measurements: measurements.json; exact detected boundary rows: shot-candidates.csv; caption intervals/text: captions.json; complete audio meter output: audio-loudness.txt.</p>'
    (root/'style-analysis.html').write_text('<!doctype html><meta charset="utf-8"><title>Illustrated history reference study</title><style>body{max-width:1100px;margin:40px auto;background:#f7f1e5;color:#282027;font:18px/1.6 system-ui}h1,h2{line-height:1.2}table{border-collapse:collapse;font-size:16px}td,th{padding:12px;border:1px solid #bcb29e;text-align:left;vertical-align:top}img{width:100%}figure{margin:30px 0}figcaption{font-size:15px}</style>'+body,encoding='utf8')

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('root');p.add_argument('--stills');p.add_argument('--output',default='worked-example-comparison.png');a=p.parse_args();root=Path(a.root);analysis(root)
    if a.stills:
        f=Path(a.stills);comparison(root,[f/'01-1.png',f/'04-1.png',f/'05-1.png',f/'02-1.png'],root/a.output,'Reference vs worked example — craft comparison, not a fidelity claim')
